    "Global timeline" : "Globale tydlyn",
    "Home timeline" : "Tuis tydlyn",
    "Mentions" : "Vermeldings",
    "Favourites" : "Gunstelinge",
    "Polls" : "Meningspeilings",
    "Edits" : "Wysigings",
    "Which posts to show" : "Watter plasings om te wys",
    "Mark all as read" : "Merk alles as gelees",
